CREATE TABLE regions (id INTEGER PRIMARY KEY, name TEXT);
CREATE TABLE states (id INTEGER PRIMARY KEY, region_id INTEGER, name TEXT);
CREATE TABLE materials (id INTEGER PRIMARY KEY, name TEXT, type TEXT);
CREATE TABLE techniques (id INTEGER PRIMARY KEY, name TEXT, category TEXT);
CREATE TABLE categories (id INTEGER PRIMARY KEY, name TEXT);
CREATE TABLE clusters (id INTEGER PRIMARY KEY, name TEXT, state TEXT, city TEXT, description TEXT);
CREATE TABLE textiles (
  id INTEGER PRIMARY KEY,
  name TEXT,
  state TEXT,
  city TEXT,
  material TEXT,
  technique TEXT,
  category TEXT,
  cluster TEXT,
  gi_tag BOOLEAN,
  primary_uses TEXT,
  short_description TEXT
);

